TextureOn = false,
TreeOn = false,
Parts = setmetatable({}, {__mode = "k"}),
Decals = setmetatable({}, {__mode = "k"}),
Textures = setmetatable({}, {__mode = "k"}),
SurfAppearances = setmetatable({}, {__mode = "k"}),
Atmospheres = setmetatable({}, {__mode = "k"}),
TreeParts = setmetatable({}, {__mode = "k"}),
