Rows       = {},
Update     = function()
local Rows = {}
if VDSettings.Misc.NextKiller then
local PlayersList = Players:GetPlayers()
table.sort(PlayersList, function(a, b)
local aAllow = a:GetAttribute("AllowKiller") or false
local bAllow = b:GetAttribute("AllowKiller") or false
if aAllow ~= bAllow then return aAllow end
return (a:GetAttribute("KillerChance") or 0) > (b:GetAttribute("KillerChance") or 0)
end)
local NextKiller = PlayersList[1]
local KillerText
if NextKiller then
KillerText = (NextKiller == Players.LocalPlayer) and "KAMU (You)" or NextKiller.Name
else
KillerText = "Waiting..."
end
table.insert(Rows, {
Text  = "Next Killer",
Value = KillerText,
Tone  = "Error",
})
else
table.insert(Rows, {
Text  = "Next Killer",
Value = "[Disabled]",
Tone  = "Muted",
})
end
if VDSettings.Misc.NextMap then
local MapFolder = workspace:FindFirstChild("Map")
local MapText
local MapTone
if MapFolder then
MapText = DetectMapName()
MapTone = "Accent"
else
MapText = "Lobby / Loading..."
MapTone = "Warning"
end
table.insert(Rows, {
Text  = "Next Map",
Value = MapText,
Tone  = MapTone,
})
else
table.insert(Rows, {
Text  = "Next Map",
Value = "[Disabled]",
Tone  = "Muted",
})
end
return Rows
end,
})
